// Euclidean distance to a capped torus


// List of other 3D SDFs: https://www.shadertoy.com/playlist/43cXRl
//
// and https://iquilezles.org/articles/distfunctions


float sdCappedTorus(in vec3 p, in vec2 sc, in float ra, in float rb)
{
    p.x = abs(p.x);
    float k = (sc.y*p.x>sc.x*p.y) ? dot(p.xy,sc) : length(p.xy);
    return sqrt( dot(p,p) + ra*ra - 2.0*ra*k ) - rb;
}

float sdSphericalArc(
    in vec3 p,      // query point in world space
    in vec3 v1,     // normalized start direction
    in vec3 v2,     // normalized end direction
    float ra,       // "major" radius of the torus (e.g., ~1.0 if on the unit sphere)
    float rb)       // "tube" radius around the arc
{
    // 1) Normalize (in case they're not already)
    vec3 n1 = normalize(v1);
    vec3 n2 = normalize(v2);

    // 2) Angle
    float dot12 = dot(n1, n2);
    float si = sqrt( abs((1.0-dot12)/2.0) );
    float co = sqrt( abs((1.0+dot12)/2.0) );
    vec2 sc = vec2(si,co); // sin and cos

    // 3) local Z = cross(n1, n2).  Need a fallback if they're collinear.
    vec3 w = cross(n1, n2);
    float wLen = length(w);
    if(wLen < 1e-8)
    {
        // degenerate case: v1 ~± v2
        // fallback: just define w as any vector perpendicular to v1
        // e.g. pick an axis not parallel to v1
        w = normalize(abs(n1.x) > 0.9 ? cross(vec3(0,1,0), n1)
                                      : cross(vec3(1,0,0), n1));
    }
    else {
        w /= wLen;
    }

    // We want local Y = v1, local Z = w
    // => local X = w x v1
    // That way, the ring is around +Z, but measured from +Y.
    vec3 yAxis = normalize(n1+n2);             // local +Y
    vec3 xAxis = normalize(cross(w, yAxis));   // local +X
    vec3 zAxis = w;                            // local +Z

    // 4) Transform p into that local coordinate system
    // pLocal = ( p·xAxis, p·yAxis, p·zAxis )
    vec3 pLocal = vec3(dot(p, xAxis),
                       dot(p, yAxis),
                       dot(p, zAxis));

    // 5) Evaluate the "capped torus" SDF in that local coordinate system
    return sdCappedTorus(pLocal, sc, ra, rb);
}

float map( in vec3 pos )
{    
    float phi1 = 2.5*(0.5+0.5*sin(iTime*1.1+3.0));
    float theta1 = 1.0;//2.5*(0.5+0.5*sin(iTime*1.5+3.0));

    float phi2 = 1.0; //2.5*(0.5+0.5*sin(iTime*1.1+3.0));
    float theta2 = 2.5*(0.5+0.5*sin(iTime*.5+3.0));

    vec3 v1 = vec3(sin(phi1)*cos(theta1),sin(phi1)*sin(theta1),cos(phi1));
    vec3 v2 = vec3(sin(phi2)*cos(theta2),sin(phi2)*sin(theta2),cos(phi2));

    return sdSphericalArc(pos, v1, v2, .3, .1);
}

// https://iquilezles.org/articles/normalsSDF
vec3 calcNormal( in vec3 pos )
{
    vec2 e = vec2(1.0,-1.0)*0.5773;
    const float eps = 0.0005;
    return normalize( e.xyy*map( pos + e.xyy*eps ) + 
					  e.yyx*map( pos + e.yyx*eps ) + 
					  e.yxy*map( pos + e.yxy*eps ) + 
					  e.xxx*map( pos + e.xxx*eps ) );
}

#if HW_PERFORMANCE==0
#define AA 1
#else
#define AA 3
#endif

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
     // camera movement	
	float an = 0.7*iTime;
	vec3 ro = vec3( 1.0*cos(an), 0.2, 1.0*sin(an) );
    vec3 ta = vec3( 0.0, 0.0, 0.0 );
    // camera matrix
    vec3 ww = normalize( ta - ro );
    vec3 uu = normalize( cross(ww,vec3(0.0,1.0,0.0) ) );
    vec3 vv =          ( cross(uu,ww));

    // render
    vec3 tot = vec3(0.0);

    #if AA>1
    for( int m=0; m<AA; m++ )
    for( int n=0; n<AA; n++ )
    {
        // pixel coordinates
        vec2 o = vec2(float(m),float(n)) / float(AA) - 0.5;
        vec2 p = (-iResolution.xy + 2.0*(fragCoord+o))/iResolution.y;
        #else    
        vec2 p = (-iResolution.xy + 2.0*fragCoord)/iResolution.y;
        #endif

	    // create view ray
        vec3 rd = normalize( p.x*uu + p.y*vv + 1.5*ww );

        // raymarch
        const float tmax = 5.0;
        float t = 0.0;
        for( int i=0; i<256; i++ )
        {
            vec3 pos = ro + t*rd;
            float h = map(pos);
            if( h<0.0001 || t>tmax ) break;
            t += h;
        }


        // shading/lighting	
        vec3 col = vec3(0.0);
        if( t<tmax )
        {
            vec3 pos = ro + t*rd;
            vec3 nor = calcNormal(pos);
            float dif = clamp( dot(nor,vec3(0.57703)), 0.0, 1.0 );
            float amb = 0.5 + 0.5*dot(nor,vec3(0.0,1.0,0.0));
            col = vec3(0.2,0.3,0.4)*amb + vec3(0.8,0.7,0.5)*dif;
        }

        // gamma        
        col = sqrt( col );
	    tot += col;
    #if AA>1
    }
    tot /= float(AA*AA);
    #endif

	fragColor = vec4( tot, 1.0 );
}
